        String protocol=source(root,"src/main/java/cn/academy/port/wireless/ClassicWirelessProtocol.java");for(String guard:new String[]{"open_windgen","menu.isFor(wind)","menu.sourcePos().equals(request.target)","menu.stillValid(player)","wind.getEnergy()","\"max_energy\",20000","wind.getBandwidth()"})check(protocol.contains(guard),"native wireless exact sender/menu/root/capacity binding");check(protocol.contains("wire.writeBoolean(true);wire.writeBlockPos(wind.getBlockPos());"),"return carries native wind menu kind");
