        String base=source(root,"src/main/java/cn/academy/port/wind/ClassicWindBaseBlockEntity.java");check(base.indexOf("tile.buffer.generate(")<base.indexOf("tile.updateTower();")&&base.indexOf("tile.updateTower();")<base.indexOf("tile.buffer.charge("),"source generation/refresh/item order");check(base.contains("tile.energyTicks==20")&&base.contains("tile.structureTicks==10")&&base.contains("publishedEnergy"),"source20tick precharge and10tick tower snapshots");check(source(root,"src/main/java/cn/academy/port/AcademyCraft.java").contains("cn.academy.port.wind.ClassicWindGenerators.register(bus);"),"real modbus integration");
